#include "polynomial.hpp"
#include <vector>
#include <cstdio>
#include <cstdlib>
#include <cmath>
using namespace showai_boundary;
static void require(bool condition,const char*label){if(!condition){std::fprintf(stderr,"arena contract failed: %s\n",label);std::abort();}}
int main(){uint32_t checks=0;
 {std::vector<uint64_t>memory(2048/8);Context c;require(c.initialize(memory.data(),2048,1000000),"initialize");{Integer source=Integer::from(c,1).shifted_left(512),captured=source;uint32_t held[32],count=0;while(c.status==SA_INK_OK){uint32_t p=c.allocate(64);if(p!=no_block)held[count++]=p;}require(c.status==SA_INK_CAPACITY,"bounded fill");require(c.begin_work(1000000),"retry work");Integer failed=captured+Integer(1);require(!failed.valid()&&c.status==SA_INK_CAPACITY,"integer OOM explicit");require(source.bits()==513&&source.data()[16]==1&&captured.data()[16]==1,"retained integer unchanged");for(uint32_t i=0;i<count;i++)c.release(held[i]);c.begin_work(1000000);Integer recovered=captured+Integer(1);require(recovered.valid()&&recovered.bits()==513&&recovered.data()[0]==1,"retry actual same captured integer");checks+=5;}require(c.live_bytes==0,"all integer refs released");checks++;}
 {std::vector<uint64_t>memory(2048/8);Context c;c.initialize(memory.data(),2048,1000000);{Vector<uint32_t,1>source(c);require(source.resize(128),"source vector");for(uint32_t i=0;i<128;i++)source[i]=i;Vector<uint32_t,1>draft=source;uint32_t held=c.allocate(900);require(held!=no_block,"occupy remaining arena");draft[0]=999;require(c.status==SA_INK_CAPACITY,"COW failure exposed");c.release(held);c.begin_work(1000000);const auto&retained=source;const auto&failed=draft;for(uint32_t i=0;i<128;i++)require(retained[i]==i&&failed[i]==i,"failed copy cannot mutate owned source");draft[0]=777;require(c.status==SA_INK_OK&&retained[0]==0&&draft[0]==777,"retry COW private branch");checks+=5;}require(c.live_bytes==0,"all vector refs released");checks++;}
 {std::vector<uint64_t>memory(1024*1024/8);Context c;c.initialize(memory.data(),1024*1024,10000000);{Integer high=Integer::from(c,1).shifted_left(65535);require(high.valid()&&high.bits()==65536,"maximum allowed exponent");Integer one=Integer::from(c,1),product=high*one;require(product.valid()&&product==high,"exact product at width boundary");Integer max=high+(high-one);require(max.valid()&&max.bits()==65536,"maximum limb value");Integer invalid=max+one;require(!invalid.valid()&&c.status==SA_INK_CAPACITY,"overflow not truncated");c.begin_work(10000000);Integer zero=max-max;require(zero.valid()&&zero.zero(),"retained operands after overflow");checks+=5;}require(c.live_bytes==0,"all wide refs released");checks++;}
 {std::vector<uint64_t>memory(1024*1024/8);PolynomialContext c;c.numbers.initialize(memory.data(),1024*1024,10000000);{Integer n=Integer::from(c.numbers,1).shifted_left(16384);Q unstoreable(n,Integer::from(c.numbers,1));require(unstoreable.valid()&&!unstoreable.stored(),"stored bits distinct from temporary");Polynomial bad(c,unstoreable);require(c.numbers.status==SA_INK_CAPACITY,"polynomial stored budget");checks+=2;}require(c.numbers.live_bytes==0,"stored failure release");checks++;}
 {std::vector<uint64_t>memory(1024*1024/8);Context c;c.initialize(memory.data(),1024*1024,10000000);{Q third(Integer::from(c,1),Integer::from(c,3));double a,b;require(third.bounds(a,b)&&a<1.0/3.0+1e-16&&std::nextafter(a,INFINITY)==b,"positive outward endpoints");Q negative=-third;double x,y;require(negative.bounds(x,y)&&x==-b&&y==-a,"negative outward endpoints");Q tiny=Q::from_double(c,0x1p-1074),smaller=tiny*tiny;require(smaller.bounds(x,y)&&x==0&&y==0x1p-1074,"underflow outward not rounded empty");Q over=Q::from_double(c,0x1.fffffffffffffp+1023);over*=over;require(over.bounds(x,y)&&x==0x1.fffffffffffffp+1023&&std::isinf(y),"overflow outward not saturated");checks+=4;}require(c.live_bytes==0,"bounds release");checks++;}
 std::printf("BOUNDARY_ARENA_ATOMIC_COW_BUDGET_OK checks=%u\n",checks);}
